// ── Dynamic title getter (class > bonus > base) ───────────────────
function getTitle(){
  // 1. Class-specific title (highest unlocked)
  if(S.playerClass && CLASS_TITLES[S.playerClass]){
    const ct = CLASS_TITLES[S.playerClass];
    let best = null;
    for(const t of ct) if(S.lv >= t.lv) best = t;
    if(best) return best;
  }
  // 2. Bonus title (first matching, prioritised by condition strength)
  for(const bt of [...BONUS_TITLES].reverse()){
    if(bt.cond(S)) return {ti:bt.ti, ds:bt.ds};
  }
  // 3. Base level title
  let t = TITLES[0];
  for(const tt of TITLES) if(S.lv >= tt.lv) t = tt;
  return t;
}
